<?php
require_once dirname(__DIR__) . '/includes/bootstrap.php'; require_admin();
$types = [
 'skills'=>['table'=>'skills','label'=>'Skills','fields'=>['name'=>'Name','category'=>'Category','proficiency'=>'Proficiency (0–100)','sort_order'=>'Sort order']],
 'projects'=>['table'=>'projects','label'=>'Projects','fields'=>['title'=>'Title','description'=>'Description','technologies'=>'Technologies','project_url'=>'Project URL','sort_order'=>'Sort order'],'image'=>true],
 'education'=>['table'=>'education','label'=>'Education','fields'=>['institution'=>'Institution','qualification'=>'Qualification','period'=>'Period','details'=>'Details','sort_order'=>'Sort order']],
 'experience'=>['table'=>'experience','label'=>'Experience','fields'=>['organization'=>'Organization','role'=>'Role','period'=>'Period','details'=>'Details','sort_order'=>'Sort order']],
 'achievements'=>['table'=>'achievements','label'=>'Achievements','fields'=>['title'=>'Title','organization'=>'Organization','achieved_on'=>'Date / year','details'=>'Details','sort_order'=>'Sort order']],
];
$type=(string)($_GET['type'] ?? 'projects'); $error=''; $success='';
if ($type==='messages') {
 if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT); $action=$_POST['action'] ?? ''; if($id && $action==='read') db()->prepare('UPDATE messages SET is_read=1 WHERE id=?')->execute([$id]); elseif($id && $action==='unread') db()->prepare('UPDATE messages SET is_read=0 WHERE id=?')->execute([$id]); elseif($id && $action==='delete') db()->prepare('DELETE FROM messages WHERE id=?')->execute([$id]); header('Location: content.php?type=messages'); exit; }
 $rows=db()->query('SELECT * FROM messages ORDER BY created_at DESC')->fetchAll();
} elseif ($type==='profile') {
 if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); try { $keys=['name','introduction','biography','email']; foreach($keys as $key) { $value=trim((string)($_POST[$key]??'')); if(strlen($value)>5000) throw new RuntimeException('A field is too long.'); if($key==='email' && !filter_var($value,FILTER_VALIDATE_EMAIL)) throw new RuntimeException('Enter a valid contact email.'); db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$key,$value]); } $image=upload_image('profile_image'); if($image) db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute(['profile_image',$image]); $success='Profile updated.'; } catch(Throwable $ex) {$error=$ex->getMessage();} }
} elseif (!isset($types[$type])) { http_response_code(404); exit('Unknown content type.'); }
elseif ($_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf(); $cfg=$types[$type]; $table=$cfg['table']; $id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT); $action=(string)($_POST['action']??'');
 try {
  if($action==='delete' && $id) { db()->prepare("DELETE FROM {$table} WHERE id=?")->execute([$id]); $success='Record deleted.'; }
  elseif(in_array($action,['save','create'],true)) {
   $values=[]; foreach($cfg['fields'] as $field=>$label) { $v=trim((string)($_POST[$field]??'')); if(strlen($v)>10000) throw new RuntimeException('A field is too long.'); if($field==='proficiency' && $v!=='' && (!ctype_digit($v)||(int)$v>100)) throw new RuntimeException('Proficiency must be between 0 and 100.'); if($field==='project_url' && $v!=='' && (!filter_var($v,FILTER_VALIDATE_URL)||!in_array(parse_url($v,PHP_URL_SCHEME),['http','https'],true))) throw new RuntimeException('Project URL must use http or https.'); $values[$field]=$v; }
   if(isset($cfg['image'])) { $image=upload_image('image'); if($image) $values['image_path']=$image; }
   if($action==='save' && $id) { $set=implode(',',array_map(fn($f)=>"{$f}=?",array_keys($values))); db()->prepare("UPDATE {$table} SET {$set} WHERE id=?")->execute([...array_values($values),$id]); }
   else { $cols=implode(',',array_keys($values)); $marks=implode(',',array_fill(0,count($values),'?')); db()->prepare("INSERT INTO {$table} ({$cols}) VALUES ({$marks})")->execute(array_values($values)); }
   $success='Changes saved.';
  }
 } catch(Throwable $ex) {$error=$ex->getMessage();}
}
$edit=null; $rows=[];
if(isset($types[$type])) { $cfg=$types[$type]; if(isset($_GET['edit']) && ctype_digit((string)$_GET['edit'])) { $s=db()->prepare('SELECT * FROM '.$cfg['table'].' WHERE id=?'); $s->execute([(int)$_GET['edit']]); $edit=$s->fetch() ?: null; } $rows=db()->query('SELECT * FROM '.$cfg['table'].' ORDER BY sort_order,id DESC')->fetchAll(); }
function setting_value(string $key,string $fallback=''): string { return portfolio_setting($key,$fallback); }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage <?=e($type)?></title><link rel="stylesheet" href="../css/style.css"><style>.admin-form input,.admin-form textarea{width:100%;margin:.3rem 0 1rem;padding:.7rem}.admin-table{width:100%;border-collapse:collapse}.admin-table td,.admin-table th{padding:.6rem;border-bottom:1px solid #aaa;text-align:left;vertical-align:top}textarea{min-height:110px}</style></head><body><main class="section container"><p><a href="dashboard.php">← Dashboard</a></p><h1><?=e($types[$type]['label']??ucfirst($type))?></h1><?php if($error): ?><p role="alert"><?=e($error)?></p><?php endif ?><?php if($success): ?><p role="status"><?=e($success)?></p><?php endif ?>
<?php if($type==='profile'): ?><form class="card admin-form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><?php foreach(['name'=>'Name','introduction'=>'Introduction','biography'=>'Biography','email'=>'Contact email'] as $key=>$label): ?><label><?=e($label)?></label><?php if(in_array($key,['biography','introduction'],true)): ?><textarea name="<?=e($key)?>" required><?=e(setting_value($key))?></textarea><?php else: ?><input name="<?=e($key)?>" value="<?=e(setting_value($key))?>" required><?php endif ?><?php endforeach ?><label>Profile image (JPEG/PNG/GIF/WebP, max 4 MB)</label><input type="file" name="profile_image" accept="image/jpeg,image/png,image/gif,image/webp"><button class="btn btn-primary">Save profile</button></form>
<?php elseif($type==='messages'): ?><table class="admin-table"><thead><tr><th>Message</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $m): ?><tr><td><strong><?=e($m['subject'])?></strong><br><?=e($m['name'])?> &lt;<?=e($m['email'])?&gt;><br><small><?=e($m['created_at'])?></small><p><?=nl2br(e($m['message']))?></p></td><td><?=$m['is_read']?'Read':'Unread'?></td><td><?php foreach(['read'=>'Mark read','unread'=>'Mark unread','delete'=>'Delete'] as $a=>$label): ?><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$m['id']?>"><button name="action" value="<?=$a?>"><?=e($label)?></button></form><?php endforeach ?></td></tr><?php endforeach ?></tbody></table>
<?php else: $cfg=$types[$type]; ?><h2><?=$edit?'Edit':'Add'?> record</h2><form class="card admin-form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e((string)($edit['id']??''))?>"><?php foreach($cfg['fields'] as $field=>$label): ?><label><?=e($label)?></label><?php if(in_array($field,['description','details'],true)): ?><textarea name="<?=e($field)?>" required><?=e((string)($edit[$field]??''))?></textarea><?php else: ?><input name="<?=e($field)?>" value="<?=e((string)($edit[$field]??''))?>" <?=in_array($field,['name','title','institution','organization','role','qualification'],true)?'required':''?>><?php endif ?><?php endforeach ?><?php if(isset($cfg['image'])): ?><label>Project image (optional; JPEG/PNG/GIF/WebP, max 4 MB)</label><input type="file" name="image" accept="image/jpeg,image/png,image/gif,image/webp"><?php endif ?><button class="btn btn-primary" name="action" value="<?=$edit?'save':'create'?>">Save</button></form><h2>Existing records</h2><table class="admin-table"><thead><tr><th>Record</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?=e((string)($row['title']??$row['name']??$row['qualification']??$row['role']??$row['institution']??''))?></td><td><a href="?type=<?=e($type)?>&amp;edit=<?=$row['id']?>">Edit</a> <form method="post" style="display:inline" onsubmit="return confirm('Delete this record?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$row['id']?>"><button name="action" value="delete">Delete</button></form></td></tr><?php endforeach ?></tbody></table><?php endif ?></main></body></html>
